-- Crilo: add 19 more memorable-number badges.
-- Scores 5 and 7 were deployed separately.
-- Preserves existing awards, wheel badges, and score rarity badges.
on conflict (badge_key) do update set name=excluded.name,description=excluded.description,requirement=excluded.requirement;

-- All funny-score descriptions explicitly say the number may occur mid-run.
update public.badges set description='Reach exactly '||(requirement->>'score')||' points at least once during an official Daily run (not necessarily your final score).'
where category='funny_score';
